<script lang="ts">
  import { onMount } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import { listen } from '@tauri-apps/api/event';
  import { LocalRgbaPresenter } from './rgba';
  import { applyDelta, LatestFrameDecoder, parseFrame, type FrameAck, type FrameHeader, type PresentationMode, type Snapshot } from './session';
  import { CameraGestureController, MutationQueue, pickCoordinates, wheelPixels, type CameraMode } from './camera-input';

  type Model = { id:string; label:string; source:string; state:string; kind:string; thumbnail?:string; error?:string };
  const lookCopy:Record<string,{title:string;description:string;media:string[]}>={
    'comic-ink':{title:'Comic Ink',description:'Bold contour and flat shadow.',media:['Ink','Shadow','Flat colour']},
    'pencil-study':{title:'Pencil Study',description:'Soft graphite study with form shading.',media:['Graphite','Form','Hatch']},
    'watercolour-wash':{title:'Watercolour Wash',description:'Gentle colour washes on paper.',media:['Wash','Colour','Paper']},
  };
  const basicLookIds=Object.keys(lookCopy);
  let snapshot=$state<Snapshot|null>(null), connection=$state('Connecting'), status=$state('Opening drawing…'), error=$state(''), pending=$state(false);
  let canvas=$state<HTMLCanvasElement>(undefined!), rgbaCanvas=$state<HTMLCanvasElement>(undefined!), viewport=$state<HTMLDivElement>(undefined!);
  let socket:WebSocket|undefined, rgbaPresenter:LocalRgbaPresenter|undefined;
  let presentationMode=$state<PresentationMode>('native_gpu'), activeMode=$state<PresentationMode|null>(null), presentationError=$state(''), nativeUnavailable:string|null=null;
  let generation=0, viewportKey='', nativeRectKey='', renderSize=$state<[number,number]>([1,1]), frameCount=0, fps=$state(0), lastFrame=$state(0), resyncing=false;
  let gestureSequence=0, activeGesture:number|undefined, navigationFrame:number|undefined, interactionTimer:ReturnType<typeof setTimeout>|undefined, nativeFocused=false;
  let cameraMode=$state<CameraMode>('select'), showModels=$state(false);
  const gestures=new CameraGestureController(), mutations=new MutationQueue();
  const domain=$derived(snapshot?.values.npr), settings=$derived(domain?.settings), models=$derived((snapshot?.values.models??[]) as Model[]);
  const activeLook=$derived(domain?.active_look??''), availableLooks=$derived(((domain?.available_looks??[]) as string[]).filter(id=>basicLookIds.includes(id)));
  const lookPreviews=$derived((snapshot?.values.look_previews??{}) as Record<string,string|undefined>), lookPreviewErrors=$derived((snapshot?.values.look_preview_errors??{}) as Record<string,string|undefined>);
  const visibleModels=$derived(models.filter(model=>model.state==='ready'));
  const selectedModel=$derived(visibleModels.find(model=>model.id===settings?.selected));
  const documentStatus=$derived(error||(pending?'Applying…':domain?.dirty?'Unsaved changes':status));
  const label=(id:string)=>lookCopy[id]?.title??id.split(/[-_]/).map(word=>word[0]?.toUpperCase()+word.slice(1)).join(' ');
  const description=(id:string)=>lookCopy[id]?.description??'A saved NPR illustration style.';
  const media=(id:string)=>lookCopy[id]?.media??['Illustration'];

  function dispatch(control:string,intent:Record<string,unknown>){if(!snapshot||resyncing||socket?.readyState!==WebSocket.OPEN)return;mutations.push(control,intent);pending=true;error='';scheduleMutations();}
  function scheduleMutations(){pending=mutations.busy;if(navigationFrame===undefined)navigationFrame=requestAnimationFrame(flushNavigation);}
  function flushNavigation(){navigationFrame=undefined;if(resyncing||!snapshot||socket?.readyState!==WebSocket.OPEN)return;const action=mutations.take(snapshot.revision);pending=mutations.busy;if(action){const {queued_at,...request}=action;socket.send(JSON.stringify({type:'action',action:request}));}}
  function resync(){gestures.cancel();activeGesture=undefined;pending=false;mutations.clear();if(resyncing)return;resyncing=true;error='';status='Refreshing drawing…';if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'refresh'}));}
  function selectModel(model:Model){if(pending||model.id===settings?.selected)return;dispatch('models',{kind:'select_model',model:model.id});showModels=false;}
  function selectLook(id:string){if(!pending&&id!==activeLook)dispatch('look',{kind:'use_look',id});}
  function save(){dispatch('save',{kind:'save_all'});}
  function syncNativeRect(){if(!viewport||nativeUnavailable)return;const rect=viewport.getBoundingClientRect();const placement={left:rect.left,top:rect.top,width:rect.width,height:rect.height,dpr:window.devicePixelRatio,visible:!document.hidden&&(activeMode==='native_gpu'||presentationMode==='native_gpu')};const key=JSON.stringify(placement);if(key===nativeRectKey)return;nativeRectKey=key;void invoke('viewport_rect',{rect:placement}).catch(reason=>presentationError=String(reason));}
  function requestViewport(interacting=false){if(socket?.readyState!==WebSocket.OPEN||!viewport||(presentationMode!=='jpeg'&&nativeUnavailable))return;const rect=viewport.getBoundingClientRect();if(!rect.width||!rect.height)return;const key=`${rect.width}:${rect.height}:${window.devicePixelRatio}:${presentationMode}`;if(key!==viewportKey){generation++;viewportKey=key;}socket.send(JSON.stringify({type:'viewport',request:{mode:presentationMode,generation,adaptive_resolution:false,css_width:rect.width,css_height:rect.height,dpr:window.devicePixelRatio,interacting,high_quality_capture:false}}));syncNativeRect();}
  function presentFrame(header:FrameHeader){if(header.generation!==generation||header.mode!==presentationMode)return;activeMode=header.mode;renderSize=header.size;frameCount++;lastFrame=performance.now();syncNativeRect();}
  function failPresentation(message:string){presentationError=message;if(presentationMode!=='jpeg'){presentationMode='jpeg';viewportKey='';requestViewport();}}
  function consumed(ack:FrameAck){if(ack.generation!==generation)return;}
  function nativeAck(ack:FrameAck){consumed(ack);void invoke('frame_consumed',{ack}).catch(reason=>failPresentation(String(reason)));}
  function beginGesture(){if(activeGesture!==undefined)return;activeGesture=++gestureSequence;dispatch('viewport',{kind:'begin_camera_gesture',gesture_id:activeGesture});}
  function endGesture(){if(activeGesture===undefined)return;dispatch('viewport',{kind:'end_camera_gesture',gesture_id:activeGesture});activeGesture=undefined;}
  function cancelGesture(){const pointer=gestures.cancel();if(pointer!==undefined&&viewport?.hasPointerCapture(pointer))viewport.releasePointerCapture(pointer);endGesture();clearTimeout(interactionTimer);requestViewport();}
  function navigate(mode:string,dx=0,dy=0,wheel=0,x=0,y=0){if((!nativeFocused&&document.activeElement!==viewport)||!viewport||resyncing)return;const rect=viewport.getBoundingClientRect();dispatch('viewport',{kind:'navigate',mode,dx,dy,wheel,x,y,width:mode==='select'?renderSize[0]:Math.max(1,Math.round(rect.width)),height:mode==='select'?renderSize[1]:Math.max(1,Math.round(rect.height)),focused:true});requestViewport(true);clearTimeout(interactionTimer);interactionTimer=setTimeout(()=>{if(!gestures.active)endGesture();requestViewport();},500);}
  function pointerDown(event:PointerEvent){if(!gestures.down(event.pointerId,event.button,event.clientX,event.clientY,cameraMode))return;event.preventDefault();viewport.focus();viewport.setPointerCapture(event.pointerId);beginGesture();}
  function pointerMove(event:PointerEvent){const move=gestures.move(event.pointerId,event.clientX,event.clientY);if(move)navigate(move.mode,move.dx,move.dy,move.wheel);}
  function pointerUp(event:PointerEvent){if(!gestures.owns(event.pointerId))return;pointerMove(event);if(gestures.up(event.pointerId,event.clientX,event.clientY)){const rect=viewport.getBoundingClientRect();const [x,y]=pickCoordinates(event.clientX,event.clientY,rect,renderSize);navigate('select',0,0,0,x,y);}if(viewport.hasPointerCapture(event.pointerId))viewport.releasePointerCapture(event.pointerId);endGesture();requestViewport();}

  onMount(()=>{
    const bootstrap=(window as any).__PLAYGROUND__;
    if(!bootstrap){connection='Disconnected';error='Open this drawing from an active Amigo scene.';return;}
    nativeUnavailable=bootstrap.native_error??null;if(nativeUnavailable)presentationMode='jpeg';
    try{rgbaPresenter=new LocalRgbaPresenter(rgbaCanvas,header=>header.generation===generation&&presentationMode==='local_rgba',presentFrame,nativeAck,failPresentation);}catch(reason){failPresentation(String(reason));}
    const listeners=Promise.all([
      listen<FrameHeader>('viewport-presented',event=>presentFrame(event.payload)),
      listen<FrameAck>('viewport-consumed',event=>consumed(event.payload)),
      listen<{slot:number;header:FrameHeader}>('viewport-rgba-frame',event=>rgbaPresenter?.push(event.payload.slot,event.payload.header)),
      listen<{generation:number;message:string}>('viewport-error',event=>{if(!event.payload.generation||event.payload.generation===generation)failPresentation(event.payload.message);}),
      listen<any>('viewport-input',event=>{const input=event.payload;if(input.kind==='focus'){nativeFocused=true;return;}if(input.kind==='cancel'){cancelGesture();nativeFocused=false;return;}nativeFocused=true;if(input.kind==='down'){if(gestures.down(1,input.button,input.x,input.y,cameraMode))beginGesture();}else if(input.kind==='move'){const move=gestures.move(1,input.x,input.y);if(move)navigate(move.mode,move.dx,move.dy,move.wheel);}else if(input.kind==='up'){const move=gestures.move(1,input.x,input.y);if(move)navigate(move.mode,move.dx,move.dy,move.wheel);if(gestures.up(1,input.x,input.y))navigate('select',0,0,0,input.x*renderSize[0]/viewport.clientWidth,input.y*renderSize[1]/viewport.clientHeight);endGesture();}else if(input.kind==='wheel'){beginGesture();navigate('zoom',0,0,input.wheel);}}),
    ]).catch(reason=>{failPresentation(String(reason));return [];});
    const decoder=new LatestFrameDecoder((image,header)=>{if(canvas.width!==image.width)canvas.width=image.width;if(canvas.height!==image.height)canvas.height=image.height;canvas.getContext('2d')?.drawImage(image,0,0);presentFrame(header);},failPresentation,ack=>{consumed(ack);if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'frame_ack',ack}));},header=>header.generation===generation&&header.mode===presentationMode);
    let frameWindow=performance.now();const fpsTimer=setInterval(()=>{const now=performance.now();fps=Math.round(frameCount*1000/(now-frameWindow));frameCount=0;frameWindow=now;},500);
    socket=new WebSocket(bootstrap.endpoint);socket.binaryType='blob';socket.onopen=async()=>{await listeners;socket?.send(JSON.stringify({version:bootstrap.version,playground:bootstrap.playground,token:bootstrap.token}));connection='Connected';requestViewport();};
    socket.onmessage=event=>{if(event.data instanceof Blob){void parseFrame(event.data).then(frame=>decoder.push(frame)).catch(reason=>error=String(reason));return;}try{const message=JSON.parse(event.data);if(message.type==='snapshot'){snapshot=message.snapshot;resyncing=false;status='Ready';scheduleMutations();}else if(message.type==='accepted'){if(mutations.accepted(message.request_id,message.revision,snapshot?.revision??0))scheduleMutations();}else if(message.type==='delta'&&snapshot){if(snapshot.revision!==message.base_revision){resync();return;}snapshot=applyDelta(snapshot,message);mutations.state(snapshot.revision);status=domain?.dirty?'Unsaved changes':'Saved';scheduleMutations();}else if(message.type==='rejected'){if(!mutations.rejected(message.request_id))return;pending=false;error=message.error.message;if(error.toLowerCase().includes('revision'))resync();}else if(message.type==='domain'&&message.payload?.message)error=message.payload.message;}catch(reason){error=String(reason);resync();}};
    socket.onclose=()=>{connection='Disconnected';pending=false;mutations.clear();status='Scene session closed';};socket.onerror=()=>error='Could not connect to the scene session.';
    const observer=new ResizeObserver(()=>requestViewport());observer.observe(viewport);const visibility=()=>{if(document.hidden)cancelGesture();syncNativeRect();},resize=()=>requestViewport();window.addEventListener('blur',cancelGesture);window.addEventListener('resize',resize);document.addEventListener('visibilitychange',visibility);
    return()=>{void listeners.then(unlisten=>unlisten.forEach(stop=>stop()));rgbaPresenter?.dispose();clearInterval(fpsTimer);cancelGesture();clearTimeout(interactionTimer);if(navigationFrame!==undefined)cancelAnimationFrame(navigationFrame);observer.disconnect();decoder.dispose();socket?.close();window.removeEventListener('blur',cancelGesture);window.removeEventListener('resize',resize);document.removeEventListener('visibilitychange',visibility);};
  });
</script>

<div class="basic-workspace">
  <header class="topbar"><button class="brand" onclick={()=>showModels=!showModels} aria-expanded={showModels}>NPR Drawing</button><span class="document-name">{selectedModel?.label??domain?.scene??'Drawing'}</span><span class:problem={!!error} class="document-status" role="status">{documentStatus}</span><div class="spacer"></div><button disabled={!domain?.can_undo||pending} onclick={()=>dispatch('history',{kind:'undo'})}>Undo</button><button disabled={!domain?.can_redo||pending} onclick={()=>dispatch('history',{kind:'redo'})}>Redo</button><button disabled={!settings||pending} onclick={()=>navigate('reset')}>Reset view</button><button class="primary" disabled={!domain||pending} onclick={save}>Save</button></header>
  <main>
    <aside class:open={showModels} class="models" aria-label="Models"><div class="panel-heading"><div><span class="eyebrow">SOURCE</span><h1>Models</h1></div><button class="close" onclick={()=>showModels=false} aria-label="Close models">×</button></div><p class="panel-copy">Choose one model. Changing it keeps the previous drawing as a local draft.</p><div class="model-list">{#each visibleModels as model}<button class:active={model.id===settings?.selected} class="model-card" disabled={pending} onclick={()=>selectModel(model)}><span class="model-preview">{#if model.thumbnail}<img src={model.thumbnail} alt="" />{:else}◇{/if}</span><span><strong>{model.label}</strong><small>{model.source} · {model.kind}</small>{#if model.error}<small class="problem">{model.error}</small>{/if}</span></button>{:else}<p class="empty">{connection==='Connected'?'No models are ready yet.':'Connecting to models…'}</p>{/each}</div></aside>
    <section class="drawing"><div class="viewport-toolbar"><button class="mobile-models" onclick={()=>showModels=!showModels}>Models</button><span>Orbit, pan and zoom directly on the drawing.</span><div class="spacer"></div><button class:active={cameraMode==='select'} onclick={()=>cameraMode='select'}>Select</button><button class:active={cameraMode==='orbit'} onclick={()=>cameraMode='orbit'}>Orbit</button></div><!-- svelte-ignore a11y_no_noninteractive_tabindex, a11y_no_noninteractive_element_interactions --><div class="viewport" bind:this={viewport} tabindex="0" role="application" aria-label="NPR drawing viewport" oncontextmenu={event=>event.preventDefault()} onpointerdown={pointerDown} onpointermove={pointerMove} onpointerup={pointerUp} onpointercancel={cancelGesture} onlostpointercapture={cancelGesture} onwheel={event=>{event.preventDefault();viewport.focus();beginGesture();navigate('zoom',0,0,-wheelPixels(event.deltaY,event.deltaMode,viewport.clientHeight));}}><canvas bind:this={canvas} class:concealed={activeMode==='local_rgba'}></canvas><canvas bind:this={rgbaCanvas} class:concealed={activeMode!=='local_rgba'}></canvas>{#if !settings}<div class="viewport-empty"><strong>{connection==='Connected'?'Preparing your drawing…':'Waiting for Amigo'}</strong><span>The paper and model will appear here.</span></div>{/if}{#if presentationError}<div class="viewport-message" role="alert">{presentationError}</div>{/if}<div class="viewport-hud">{activeMode?'Drawing ready':'Preparing render'}{#if fps} · {fps} FPS{/if}{#if lastFrame} · {renderSize[0]} × {renderSize[1]}{/if}</div></div></section>
    <aside class="looks" aria-label="Style presets"><div class="panel-heading"><div><span class="eyebrow">STYLE PRESETS</span><h1>Looks</h1></div></div><p class="panel-copy">A look is a complete illustration recipe. Pick one to preview it immediately.</p><div class="look-list">{#each availableLooks as id}<button class:active={id===activeLook} class="look-card" disabled={pending} onclick={()=>selectLook(id)}><span class="look-preview" class:pending-preview={!lookPreviews[id]} aria-hidden="true">{#if lookPreviews[id]}<img src={lookPreviews[id]} alt="" />{:else if lookPreviewErrors[id]}<span>Preview unavailable</span>{:else}<i></i><i></i><i></i><span>Rendering…</span>{/if}</span><span class="look-content"><strong>{label(id)}</strong><small>{lookPreviewErrors[id]??description(id)}</small><span class="media">{#each media(id) as item}<em>{item}</em>{/each}</span></span></button>{:else}<p class="empty">The three Basic looks are unavailable in this mod.</p>{/each}</div></aside>
  </main>
</div>

<style>
  .look-preview img { display: block; width: 100%; height: 100%; object-fit: cover; }
  .look-preview.pending-preview { display: grid; place-items: center; color: #68665d; font-size: 9px; }
  :global(*){box-sizing:border-box}:global(body){margin:0;background:#111315;color:#e8e5df;font:13px/1.45 Inter,"Segoe UI",sans-serif}:global(button){border:1px solid #41413e;border-radius:7px;background:#272826;color:inherit;padding:7px 10px;cursor:pointer;font:inherit}:global(button:hover:not(:disabled)){background:#393a36}:global(button:disabled){cursor:default;opacity:.45}:global(button:focus-visible){outline:2px solid #d3aa65;outline-offset:2px}.basic-workspace{height:100dvh;display:grid;grid-template-rows:52px minmax(0,1fr);overflow:hidden;background:#171816}.topbar{display:flex;align-items:center;gap:12px;padding:0 16px;border-bottom:1px solid #363632;background:#20211e}.brand{border:0;background:transparent;padding-left:0;color:#fbf6eb;font-weight:700;letter-spacing:.02em}.brand:hover:not(:disabled){background:transparent;color:#ddb56c}.document-name{color:#aaa99f}.document-status{color:#9ebea2;font-size:12px}.problem{color:#ee9a87}.spacer{flex:1}.primary{border-color:#b58d4c;background:#7c5c2d;color:#fff8e9}.primary:hover:not(:disabled){background:#946c35}main{display:grid;grid-template-columns:244px minmax(0,1fr) 292px;min-height:0}aside{min-height:0;overflow:auto;background:#20211e}.models{border-right:1px solid #363632;padding:18px 14px}.looks{border-left:1px solid #363632;padding:18px 14px}.panel-heading{display:flex;align-items:start;justify-content:space-between}.eyebrow{display:block;color:#d1a75f;font-size:10px;font-weight:700;letter-spacing:.11em}h1{margin:2px 0 0;color:#faf5ea;font-size:18px;font-weight:600}.close{display:none;border:0;background:transparent;font-size:18px}.panel-copy{margin:14px 0 16px;color:#aead9f;font-size:12px}.model-list,.look-list{display:grid;gap:8px}.model-card,.look-card{width:100%;display:flex;align-items:center;gap:10px;padding:8px;text-align:left}.model-card.active,.look-card.active{border-color:#c49a54;background:#38342a;box-shadow:inset 3px 0 #d3aa65}.model-preview{width:44px;height:44px;display:grid;place-items:center;flex:0 0 auto;overflow:hidden;border-radius:4px;background:#171816;color:#c5b188;font-size:25px}.model-preview img{width:100%;height:100%;object-fit:contain}strong{display:block;font-weight:600}small{display:block;color:#a8a79f;font-size:11px}.drawing{position:relative;display:flex;min-width:0;min-height:0;flex-direction:column;background:#141512}.viewport-toolbar{display:flex;min-height:42px;align-items:center;gap:7px;padding:6px 10px;border-bottom:1px solid #30312d;color:#989a90;font-size:11px}.viewport-toolbar button{padding:4px 8px;font-size:11px}.viewport-toolbar button.active{border-color:#b58d4c;background:#51432a;color:#fff8e9}.mobile-models{display:none}.viewport{position:relative;min-height:0;flex:1;overflow:hidden;outline:none}canvas{display:block;width:100%;height:100%;object-fit:contain;touch-action:none}.concealed{visibility:hidden}.viewport-empty{position:absolute;inset:0;display:grid;place-content:center;gap:6px;color:#a6a89b;text-align:center}.viewport-empty strong{color:#e3dece;font-size:17px}.viewport-message{position:absolute;top:12px;right:12px;max-width:320px;padding:8px 10px;border:1px solid #824e43;border-radius:5px;background:#321f1d;color:#efad9f;font-size:11px}.viewport-hud{position:absolute;bottom:12px;left:12px;padding:5px 8px;border-radius:4px;background:#12130fcc;color:#bbb9ad;font:10px ui-monospace,SFMono-Regular,Consolas,monospace;pointer-events:none}.look-card{align-items:stretch;min-height:86px}.look-preview{position:relative;width:58px;min-height:66px;flex:0 0 auto;overflow:hidden;border-radius:4px;background:#e9e1ce}.look-preview i{position:absolute;display:block;transform:rotate(-24deg);background:#2b2822}.look-preview i:nth-child(1){top:14px;left:5px;width:54px;height:3px}.look-preview i:nth-child(2){top:30px;left:2px;width:54px;height:2px;opacity:.62}.look-preview i:nth-child(3){top:44px;left:8px;width:44px;height:8px;opacity:.24}.look-content{display:flex;min-width:0;flex:1;flex-direction:column;gap:3px}.media{display:flex;flex-wrap:wrap;gap:3px;margin-top:auto}em{border-radius:10px;background:#33342f;color:#c5c1b7;padding:1px 6px;font-size:9px;font-style:normal}.empty{color:#9b9b90;font-size:12px}@media(max-width:840px){main{grid-template-columns:minmax(0,1fr) 236px}.models{position:absolute;z-index:2;top:0;bottom:0;left:0;display:none;width:min(280px,88vw);box-shadow:12px 0 42px #0008}.models.open{display:block}.close,.mobile-models{display:block}}@media(max-width:620px){.basic-workspace{grid-template-rows:50px minmax(0,1fr)}.topbar{gap:7px;padding:0 10px}.document-name{display:none}main{grid-template-columns:minmax(0,1fr)}.looks{max-height:220px;border-top:1px solid #363632;border-left:0;padding:10px}.looks .panel-heading,.looks .panel-copy{display:none}.look-list{display:flex;overflow-x:auto}.look-card{min-width:220px}.viewport-toolbar>span{display:none}}
</style>
